#include <cstddef>
#include <memory>
#include <utility>

class UploadPacket
{
public:
    explicit UploadPacket(std::size_t bytes)
        : payload_(
            std::make_unique<PacketStorage>(bytes)
        )
    {
    }

    UploadPacket(const UploadPacket&) = delete;
    UploadPacket& operator=(const UploadPacket&) = delete;

    UploadPacket(UploadPacket&& other) noexcept
        : payload_(
            other.payload_
                ? std::make_unique<PacketStorage>(
                    other.payload_->bytes()
                  )
                : nullptr
        )
    {
    }

    ~UploadPacket() = default;

    bool empty() const noexcept
    {
        return payload_ == nullptr;
    }

    std::size_t bytes() const noexcept
    {
        return payload_
            ? payload_->bytes()
            : 0;
    }

    const PacketStorage* payload() const noexcept
    {
        return payload_.get();
    }

private:
    std::unique_ptr<PacketStorage> payload_;
};

